---@class SimpleSlidingDoor
---@field gateTF                 UnityEngine.Transform
---@field closedTrans            UnityEngine.Transform
---@field openTrans              UnityEngine.Transform
---@field params                 Engine.Modules.LuaParameters 
local SimpleSlidingDoor = Class('SimpleSlidingDoor')

-- 外部使用时:
-- local SimpleSlidingDoor = import('Game.DreamSpace.ElectricalSystem.Appliance.SimpleSlidingDoor')

-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local QuestUtils = import('Game.DreamSpace.Quest.QuestUtils')
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

---@type DreamSpaceSounds
local DreamSpaceSounds = import('Game.DreamSpace.Tools.DreamSpaceSounds'):GetInstance()


---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Animation = CS.UnityEngine.Animation
local Animator = CS.UnityEngine.Animator
local Input = CS.UnityEngine.Input
local KeyCode = CS.UnityEngine.KeyCode
local Mathf = CS.UnityEngine.Mathf
local Criware = CS.CriWare


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters

local ElectricalTrigger = CS.ElectricalSystem.ElectricalTrigger
local Interrupter = CS.ElectricalSystem.ElectricalSwitch.Interrupter
local OnOff = CS.Game.OnOff



-- ========================================================





-- ========================================================

function SimpleSlidingDoor:__init()
    self.controller = nil

    self.currentMoveVelocity = Vector3.zero
end


function SimpleSlidingDoor:__delete()
end


  


function SimpleSlidingDoor:Start()
    assert( self.gateTF and self.closedTrans and self.openTrans and self.params )

    self:BindUpdateFunction()
    
    self:GetInspectorParams()
    
    self.isMovingTowards = false

    self.openTimes = 0

    self.endY = 0
end


function SimpleSlidingDoor:BindUpdateFunction()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
end


function SimpleSlidingDoor:GetInspectorParams()
    self.duration               = LuaParametersReader.Read( self.params, "smoothTime", LuaParametersReader.Type.Float ) -- 0.5
    self.firstTimeDelay         = LuaParametersReader.Read( self.params, "firstTimeDelay", LuaParametersReader.Type.Float ) -- 5.0

    local isDoorInitOpen = LuaParametersReader.Read( self.params, "isDootInitOpen", LuaParametersReader.Type.Bool ) -- false, 初始阶段, 门是开的还是关的
    assert( self.duration and self.firstTimeDelay and type(isDoorInitOpen) == "boolean" )

    if isDoorInitOpen then
        self.gateTF.position = self.openTrans.position
    else
        self.gateTF.position = self.closedTrans.position
    end
end


function SimpleSlidingDoor:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end




function SimpleSlidingDoor:Update()
    if (not self.isMovingTowards) then return end

    if (self.isMovingTowards and not self.isReachTarget) then
        local t = (Time.time - self.startTime) / self.duration
        local newY = Mathf.SmoothStep(self.startY, self.endY, t)
        self.gateTF.position = Vector3(self.gateTF.position.x, newY, self.gateTF.position.z)
    end

    if (Mathf.Abs(self.gateTF.position.y - self.endY) <= Mathf.Epsilon) then
        self.isReachTarget = true
        self.isMovingTowards = false
        if (self.wasMovingTowards ~= self.isMovingTowards) then
            self:OnDoorStopSliding()
        end
    end

    self.wasMovingTowards = self.isMovingTowards
end

function SimpleSlidingDoor:OnDoorStopSliding()
    DreamSpaceSounds.Play( DreamSpaceSounds.sfx.electricDoorClose, self.gateTF.gameObject )
end




function SimpleSlidingDoor:Open(isOpen)                          -- 外部调用, 设置门 开启/关闭

    self.openTimes = self.openTimes + 1

    if (self.openTimes == 1) then
        DreamSpaceSounds.Play( DreamSpaceSounds.sfx.electricDoorOpen, self.gateTF.gameObject )
        self.atomSource = KTool.GetComponent(self.gateTF.gameObject, typeof(Criware.CriAtomSource))
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(self.firstTimeDelay))
        cs_coroutine.yield_return(self:TriggerDoorMovement(isOpen))
    else
        self:TriggerDoorMovement(isOpen) 
    end

end


function SimpleSlidingDoor:TriggerDoorMovement(isOpen)
    if (not self.isMovingTowards) then
        self.isMovingTowards = true
        self.isReachTarget = false

        if isOpen then
            self.startY = self.closedTrans.position.y
            self.endY = self.openTrans.position.y
            if isNotNull(self.atomSource) then
                self.atomSource.volume = 1
            end
        else
            self.startY = self.openTrans.position.y
            self.endY = self.closedTrans.position.y
            if isNotNull(self.atomSource) then
                self.atomSource.volume = 0.3
            end
        end

        self.startTime = Time.time
        self.actualDuration = self.duration

    else
        self.startY = self.gateTF.position.y
        self.endY = isOpen and self.openTrans.position.y or self.closedTrans.position.y

        self.startTime = Time.time
        local speed = Mathf.Abs(self.closedTrans.position.y - self.openTrans.position.y) / self.duration
        self.actualDuration = Mathf.Abs(self.startY - self.endY) / speed   -- d/s = v
    end

    DreamSpaceSounds.Play( DreamSpaceSounds.sfx.electricDoorMove, self.gateTF.gameObject )
end



function SimpleSlidingDoor:SetDoorOpenInitially(isOpen)
    local y = isOpen and self.openTrans.position.y or self.closedTrans.position.y
    self.gateTF.position = Vector3(self.gateTF.position.x, y, self.gateTF.position.z)
end

-- 返回 门是否正在移动
function SimpleSlidingDoor:IsDoorMoving()
    return self.isMovingTowards
end




return SimpleSlidingDoor

